                    x,y=stack.pop(); pts.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]!=0 and q not in seen:
                            seen.add(q); stack.append(q)
                comps.append(pts)
    comps.sort(key=lambda p:min(x for x,y in p))
